<?phprequire_once "db.php";$id = $_GET['id'] ?? '';if (!ctype_digit((string)$id) || (int)$id < 1) {    exit("Invalid Attendance ID");}$result = pg_query_params(    $conn,    "SELECT * FROM attendance WHERE attendance_id = $1",    [$id]);if (!$result || pg_num_rows($result) === 0) {    exit("Attendance Record Not Found");}$record = pg_fetch_assoc($result);$message = "";if (isset($_POST['update_attendance'])) {    $status = $_POST['status'];    $date = $_POST['attendance_date'];    if (!in_array($status, ['Present', 'Absent'], true)) {        $message = "Invalid attendance status.";    } else {        $update = pg_query_params(            $conn,            "UPDATE attendance             SET status = $1, attendance_date = $2             WHERE attendance_id = $3",            [$status, $date, $id]        );        if ($update) {            header("Location: attendance.php");            exit();        } else {            $message = "Error: " . pg_last_error($conn);        }    }}?><!DOCTYPE html><html><head>    <title>Edit Attendance</title>    <link rel="stylesheet" href="attendance.css"></head><body><div class="attendance-container"><div class="attendance-form">    <h2>Edit Attendance</h2>    <p class="message">        <?php echo htmlspecialchars($message); ?>    </p>    <form method="POST">        <label>Attendance Date</label>        <input type="date"        name="attendance_date"        value="<?php echo htmlspecialchars($record['attendance_date']); ?>"        required>        <label>Attendance Status</label>        <select name="status" required>            <option value="Present"            <?php if ($record['status'] === 'Present') echo 'selected'; ?>>                Present            </option>            <option value="Absent"            <?php if ($record['status'] === 'Absent') echo 'selected'; ?>>                Absent            </option>        </select>        <button type="submit" name="update_attendance">            Update Attendance        </button>    </form>    <br>    <a href="attendance.php">Back to Attendance</a></div></div></body></html>